package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaIdDraft5 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_undressing" to DuaText("Saat Melepas Pakaian", "Dengan menyebut nama Allah.", "Saat melepas pakaian (untuk mandi atau berganti pakaian).", "Ia menjadi penghalang antara mata jin dan aurat seseorang."),
        "dua_ilbas_jadidan" to DuaText("Melihat Seseorang dengan Pakaian Baru", "Pakailah yang baru, hidup terpuji dan mati syahid.", "Saat melihat saudara muslim memakai baju baru.", "Nabi ﷺ mengucapkan doa ini saat melihat Umar (RA) mengenakan pakaian baru."),
        "dua_hajj_la_riya" to DuaText("Haji Bebas Pamer", "Ya Allah, jadikanlah itu ibadah haji tanpa pamer dan tanpa mencari ketenaran.", "Untuk keikhlasan saat berniat haji.", "Nabi ﷺ mengucapkan doa ini pada saat haji."),
        "dua_q_muslimayni_laka" to DuaText("Doa Ibrahim & Ismail (AS) — Jadikan Kami Tunduk", "Ya Tuhan kami, jadikanlah kami berdua yang tunduk kepada-Mu dan dari keturunan kami menjadi suatu bangsa yang tunduk kepada-Mu. Tunjukkan kepada kami tata cara ibadah kami dan terimalah taubat kami. Sesungguhnya Engkau Maha Penerima taubat lagi Maha Penyayang.", "Doa ketundukan untuk diri sendiri dan keturunannya.", "Doa yang dipanjatkan ketika membangun Ka'bah."),
        "dua_q_iftah_baynana" to DuaText("Doa Syu'aib (AS) — Hakim di Antara Kita", "Ya Tuhan kami, hakimilah antara kami dan kaum kami dengan sebenar-benarnya, dan Engkaulah sebaik-baik hakim.", "Untuk penilaian antara kebenaran dan kepalsuan.", "Doa Syu'ayb (AS) ketika kaumnya menolaknya."),
        "dua_q_la_akuna_zahiran" to DuaText("Doa Musa (AS) — Tidak Pernah Menjadi Penolong Penjahat", "Ya Tuhanku, karena nikmat yang Engkau anugerahkan kepadaku, aku tidak akan pernah menjadi penolong para penjahat.", "Syukur atas nikmat Allah dan ikrar untuk tidak menolong orang yang zalim.", "Janji Musa (AS) setelah taubatnya."),
        "dua_q_nuh_unsurni" to DuaText("Doa Nuh (AS) — Tolonglah Aku, Mereka Menyangkal Aku", "Ya Tuhanku, tolonglah aku, karena mereka telah mengingkari aku.", "Ketika orang-orang menyangkal Anda dan menolak kebenaran.", "Doa Nuh (AS) yang terkabul."),
        "dua_q_ihkum_bil_haqq" to DuaText("Ya Tuhanku, Hakimlah dengan sebenar-benarnya", "Tuhanku, hakimlah dengan sebenar-benarnya. Dan Tuhan kami Maha Penyayang, yang dimintai pertolongan terhadap apa yang kamu gambarkan.", "Dalam menghadapi kebohongan dan tuduhan palsu.", "Sebuah doa yang diajarkan kepada Nabi ﷺ."),
        "dua_ghalabatid_dayn" to DuaText("Berlindung dari Hutang dan Musuh yang Menghancurkan", "Ya Allah, aku berlindung kepada-Mu dari terlilit hutang, dari dikuasai musuh, dan dari sombongnya musuh.", "Perlindungan dari beban hutang dan dominasi musuh.", "Nabi ﷺ biasa berlindung dari hal-hal ini."),
        "dua_faqr_qillah_dhillah" to DuaText("Perlindungan dari Kemiskinan dan Penghinaan", "Ya Allah, aku berlindung kepada-Mu dari kemiskinan, kelangkaan dan kehinaan, dan dari zalim atau zalim kepada-Mu.", "Agar aman dari kesulitan, kekurangan dan penghinaan.", "Perlindungan yang diajarkan oleh Nabi ﷺ."),
        "dua_five_things_new_muslim" to DuaText("Maafkan, Kasihanilah, Bimbing, Sembuhkan, Berikan", "Ya Allah, ampunilah aku, kasihanilah aku, bimbinglah aku, berilah aku kesejahteraan dan rezekilah aku.", "Nabi ﷺ mengajarkan doa ini, bersama dengan doanya, kepada umat Islam yang baru.", "Nabi ﷺ bersabda: Kata-kata ini dikumpulkan untukmu di dunia dan di akhirat."),
        "dua_ruku_laka_raka_tu" to DuaText("Di Ruku - Kepadamu Aku Membungkuk", "Ya Allah, kepadaMu aku bersujud, kepadaMu aku beriman, dan kepadaMu aku berserah diri. Pendengaranku, penglihatanku, akal budiku, tulang-tulangku dan urat-uratku telah ditundukkan di hadapan-Mu.", "Dalam ruku (khususnya dalam shalat sunnah).", "Nabi ﷺ membacakan ini di ruku."),
        "dua_sujood_laka_sajadtu" to DuaText("Dalam Sujud — Kepadamu aku sujud", "Ya Allah, kepadaMu aku bersujud, kepadaMu aku beriman, dan kepadaMu aku berserah diri. Wajahku bersujud kepada Dzat yang menciptakannya, membentuknya, dan memunculkan pendengaran dan penglihatannya. Maha Suci Allah, sebaik-baik pencipta.", "Dalam sujud (terutama dalam shalat sunnah).", "Nabi ﷺ membacakan ini dalam sujud."),
        "dua_ruku_sujood_subhanaka" to DuaText("Maha Suci Engkau, Tuhan kami — Maafkan Aku", "Maha Suci Engkau ya Allah Tuhan kami dan segala puji bagiMu. Ya Allah, maafkan aku.", "Dalam ruku dan sujud.", "Aisha (RA) : Nabi ﷺ sering mengucapkan hal ini dalam ruku dan sujud."),
        "dua_q_musa_li_akhi" to DuaText("Doa Musa (AS) — Maafkan Aku dan Saudaraku", "Ya Tuhanku, ampunilah aku dan saudaraku dan masukkan kami ke dalam rahmat-Mu, karena Engkaulah Yang Maha Penyayang di antara Yang Maha Penyayang.", "Pengampunan untuk diri sendiri dan saudara atau orang yang dicintai.", "Doa Musa (AS) untuk Harun (AS)."),
        "dua_q_ufawwidu_amri" to DuaText("Aku Percayakan Urusanku Kepada Allah", "Dan aku mempercayakan urusanku kepada Allah. Sesungguhnya Allah Maha Melihat hamba-hamba-Nya.", "Ketika orang menentang Anda dan masalahnya harus diserahkan kepada Allah.", "Perkataan orang mukmin dari kaum Firaun; Allah kemudian melindunginya dari rencana jahat mereka."),
        "dua_q_hawariyyun" to DuaText("Dua Para Murid — Catat Kami Bersama Para Saksi", "Ya Tuhan kami, kami telah beriman kepada apa yang Engkau turunkan dan kami telah mengikuti Rasul, maka catatlah kami di antara para saksi.", "Untuk ketabahan dalam iman dan mengikuti Rasul.", "Doa para murid Yesus (AS)."),
        "dua_q_la_tukhzini" to DuaText("Doa Ibrahim (AS) — Jangan Permalukan Aku", "Dan janganlah kamu mempermalukan Aku pada hari mereka dibangkitkan.", "Agar aman dari aib di hari kiamat.", "Doa Ibrahim (AS) untuk Akhirat."),
        "dua_iftar_laka_sumtu" to DuaText("Iftar — Untukmu aku berpuasa", "Ya Allah, karenaMu aku telah berpuasa dan dengan rezekiMu aku berbuka.", "Saat berbuka puasa (doa buka puasa yang terkenal).", "Nabi ﷺ mengatakan hal ini saat berbuka puasa. Merupakan riwayat mursal yang diperkuat dengan riwayat lain; membacanya saat berbuka puasa adalah amalan kaum Hanafi dan mayoritas."),
        "dua_iftar_ibn_umar" to DuaText("Buka Puasa — Dengan Rahmat-Mu yang Besar, Maafkan Aku", "Ya Allah, aku mohon kepada-Mu dengan rahmat-Mu yang meliputi segala sesuatu, ampunilah aku.", "Saat berbuka puasa — Abdullah ibn Amr (RA) mengucapkan doa ini; doa orang yang berpuasa saat berbuka puasa tidak ditolak.", "Hadis: Doa orang yang berpuasa pada saat berbuka puasa tidak ditolak."),
        "dua_inni_saim" to DuaText("Bila Diprovokasi Saat Puasa", "Aku sedang berpuasa, aku sedang berpuasa.", "Ketika seseorang menghinamu atau bertengkar denganmu saat berpuasa.", "Nabi ﷺ bersabda: Puasa adalah tameng, maka orang yang berpuasa tidak boleh berkata-kata kotor atau berbuat jahil — jika ada yang bertengkar, ucapkanlah dua kali."),
        "dua_eid_takbeer" to DuaText("Takbir Menjelang Idul Fitri", "Allah Maha Besar, Allah Maha Besar, tidak ada Tuhan selain Allah, dan Allah Maha Besar, Allah Maha Besar, dan segala puji bagi Allah.", "Mulai dari malam hilal hingga salat Idul Fitri, khususnya dalam perjalanan menuju lokasi Idul Fitri.", "Perintah Al-Qur'an: 'supaya kamu menyempurnakan penghitungan dan mewartakan kebesaran Allah' (al-Baqarah 2:185). Ibnu Mas'ud (RA) mengucapkan takbir ini."),
        "dua_ahsin_aqibatana" to DuaText("Jadikan Akhir Kita Baik dalam Segala Urusan", "Ya Allah, jadikanlah akhir kami baik dalam segala urusan, dan peliharalah kami dari aib di dunia dan siksa di akhirat.", "Untuk hasil yang baik dalam segala hal.", "Barangsiapa yang mengucapkan doa ini dan meninggal sebelum diadili, maka ia mati (aman dari cobaan)."),
        "dua_fadlika_wa_rahmatik" to DuaText("Aku Meminta Karunia dan Rahmat-Mu", "Ya Allah, aku memohon kepada-Mu karunia dan rahmat-Mu, karena tidak ada seorang pun yang memilikinya kecuali Engkau.", "Saat meminta rezeki dan rahmat.", "Para tamu datang kepada Nabi ﷺ ketika tidak ada makanan; dia mengucapkan doa ini, dan kemudian hadiah tiba."),
        "dua_allahu_akbar_kabira_2696" to DuaText("Kata-kata yang Diajarkan kepada Orang Badui", "Tidak ada yang berhak disembah kecuali Allah, sendiri, tanpa sekutu. Allah Maha Besar, Maha Besar; pujian yang melimpah hanya untuk Allah; Maha Suci Allah, Tuhan semesta alam; dan tidak ada daya dan kekuatan kecuali dengan izin Allah Yang Maha Kuasa lagi Maha Bijaksana.", "Ungkapan dzikir dan doa yang komprehensif — diajarkan kepada seorang Badui.", "Setelah itu dia diajari mengucapkan 'Allahummaghfir li warhamni wahdini warzuqni'."),
        "dua_ma_qaddamtu_akhkhartu" to DuaText("Maafkan Apa yang Saya Kirim Sebelum dan Sesudahnya", "Ya Allah, ampunilah aku atas dosa-dosa yang aku lakukan sebelum dan sesudahnya, apa yang aku lakukan secara sembunyi-sembunyi dan apa yang aku lakukan secara terang-terangan, perbuatan-perbuatanku yang berlebih-lebihan, dan apa yang Engkau lebih mengetahui daripada aku. Engkaulah yang memajukan dan yang memundurkan; tidak ada Tuhan selain Engkau.", "Setelah tashahhud dan salawat, sebelum salam.", "Nabi ﷺ membacakan ini di akhir shalat, antara tashahhud dan salam."),
        "dua_jiddi_wa_hazli" to DuaText("Maafkan Keseriusan dan Lelucon Saya", "Ya Allah, ampunilah dosa-dosa yang kulakukan dengan sungguh-sungguh dan bercanda, karena kesalahan dan kesengajaan, dan semua itu ada pada diriku.", "Pengampunan atas segala jenis dosa, baik yang diketahui maupun yang tidak.", "Istighfar Nabi yang komprehensif ﷺ."),
        "dua_rising_ruku_mil" to DuaText("Setelah Ruku — Pujian Memenuhi Surga", "Ya Tuhan kami, milik-Mu segala puji, memenuhi langit, memenuhi bumi, dan memenuhi apa pun yang Engkau kehendaki setelah itu.", "Setelah bangun dari ruku, bersama dengan 'Rabbana lakal-hamd'.", "Nabi ﷺ mengatakan hal ini ketika bangun dari ruku."),
        "dua_istiftah_kabira" to DuaText("Allah Maha Besar lagi Maha Terpuji", "Allah Maha Besar, Maha Besar; pujian yang melimpah hanya untuk Allah; dan Alhamdulillah pagi dan petang.", "Saat memulai salat (salah satu bentuk puji-pujian pembuka).", "Nabi ﷺ bersabda: dibukakan pintu surga untuk itu."),
        "dua_q_ashku_bathhi" to DuaText("Doa Yaqub (AS) — Aku Hanya Mengeluh Kepada Allah", "Aku mengadukan kesedihanku dan kesedihanku hanya kepada Allah.", "Dalam kesedihan dan perpisahan yang mendalam.", "Ya'qub (AS) mengatakan hal ini dalam perpisahannya dengan Yusuf (AS)."),
        "dua_q_khayrun_hafiza" to DuaText("Allah adalah Pelindung Terbaik", "Allah adalah sebaik-baik Pelindung, dan Dialah Yang Maha Penyayang di antara Yang Maha Penyayang.", "Saat mengirim anak atau orang tersayang dalam perjalanan.", "Ya'qub (AS) mengatakan hal tersebut sambil menitipkan putranya kepada Allah."),
        "dua_q_aqraba_rashada" to DuaText("Semoga Tuhanku Membimbingku Lebih Dekat ke Kanan", "Mudah-mudahan Tuhanku akan memberi petunjuk kepadaku kepada apa yang lebih dekat dengan amal shaleh.", "Saat mencari cara yang lebih baik dalam beberapa hal.", "Nabi ﷺ diberitahu untuk mengatakan ini ketika lupa."),
        "dua_q_sawa_as_sabil" to DuaText("Doa Musa (AS) — Bimbing Aku ke Jalan yang Benar", "Mungkin Tuhanku akan memberi petunjuk padaku ke jalan yang benar.", "Saat memulai perjalanan baru atau jalan yang asing.", "Musa (AS) mengatakan ini sambil berbalik ke arah Madyan."),
        "dua_q_not_among_wrongdoers" to DuaText("Jangan tempatkan aku di antara orang-orang yang zalim", "Ya Tuhanku, jangan tempatkan aku di antara orang-orang yang zalim.", "Sebuah doa memohon kepada Allah untuk menjauhkan seseorang dari orang-orang yang zalim.", "Sebuah doa memohon kepada Allah untuk menjauhkan seseorang dari orang-orang yang zalim."),
        "dua_q_do_not_make_us_trial" to DuaText("Jangan Jadikan Kami Cobaan", "Ya Tuhan kami, jangan jadikan kami cobaan bagi orang-orang kafir, dan ampunilah kami ya Tuhan kami. Sesungguhnya Engkaulah Yang Maha Kuasa lagi Maha Bijaksana.", "Doa Ibrahim (AS) dan para sahabatnya.", "Doa Ibrahim (AS) dan para sahabatnya."),
        "dua_morning_witness" to DuaText("Saksi Pagi Tauhid", "Ya Allah, aku telah memasuki pagi hari dengan menyeru kepada-Mu, para pembawa Arsy-Mu, para malaikat-Mu, dan seluruh makhluk-Mu untuk bersaksi bahwa Engkaulah Allah, tidak ada Tuhan selain Engkau, sendiri, tanpa sekutu, dan bahwa Muhammad ﷺ adalah hamba dan Utusan-Mu.", "Riwayat tersebut menyebutkan mengucapkannya empat kali di pagi hari.", "Riwayat tersebut menyebutkan mengucapkannya empat kali di pagi hari."),
        "dua_evening_witness" to DuaText("Sore Saksi Tauhid", "Ya Allah, aku telah memasuki malam ini dengan menyeru kepada-Mu, para pembawa Arsy-Mu, para malaikat-Mu, dan seluruh ciptaan-Mu untuk bersaksi bahwa Engkaulah Allah, tidak ada Tuhan selain Engkau, sendiri, tanpa sekutu, dan bahwa Muhammad ﷺ adalah hamba dan Utusan-Mu.", "Riwayat tersebut menyebutkan mengucapkannya empat kali pada malam hari.", "Riwayat tersebut menyebutkan mengucapkannya empat kali pada malam hari."),
        "dua_morning_blessing" to DuaText("Pagi Terima kasih atas berkahnya", "Ya Allah, nikmat apa pun yang aku atau makhluk-Mu terima pagi ini adalah dari-Mu sendiri, tanpa sekutu; jadi milik-Mu segala puji dan syukur.", "Dzikir pagi rasa syukur atas nikmat Allah.", "Dzikir pagi rasa syukur atas nikmat Allah."),
        "dua_evening_blessing" to DuaText("Malam Terima Kasih atas Berkah", "Ya Allah, nikmat apa pun yang aku atau makhluk-Mu terima malam ini adalah dari-Mu sendiri, tanpa sekutu; jadi milik-Mu segala puji dan syukur.", "Dzikir malam syukur atas nikmat Allah.", "Dzikir malam syukur atas nikmat Allah."),
    )
}
